      '.anatomy-clinical-panel{display:grid;grid-template-columns:minmax(120px,.7fr) minmax(0,1.3fr);gap:5px 12px;margin-top:8px;padding:8px 10px;border-left:4px solid #7c3aed;background:#f5f3ff;color:#4c1d95;}',
