    kidneys: ['kidney', 'renal'], uterus: ['womb'], femur: ['thigh bone'], tibia: ['shinbone', 'shin bone'],
    fibula: ['calf bone'], pelvis: ['hip bone'], brainstem: ['brain stem'], vertebral: ['spine', 'backbone']
