              // Falciform ligament
              cCtx.beginPath(); cCtx.moveTo(W * 0.52, H * 0.295); cCtx.lineTo(W * 0.52, H * 0.325);
              cCtx.strokeStyle = '#5d4037'; cCtx.lineWidth = 0.5; cCtx.stroke();

              // ── Stomach (with rugae folds + greater/lesser curvature) ──
              cCtx.beginPath();
