                var age = (Date.now() - cp.born) * 0.001;
                if (age > 2) return;
                var cpx2 = cp.x * W + cp.vx * age * W * 0.15;
                var cpy2 = cp.y * H + cp.vy * age * H * 0.2 + age * age * H * 0.08;
