                cCtx.fillStyle = '#ef444490'; cCtx.fill(); cCtx.strokeStyle = '#dc2626'; cCtx.lineWidth = 1; cCtx.stroke();
                cCtx.font = 'bold 7px Inter, system-ui, sans-serif';
