                var isMid = (sel.id && (sel.id.indexOf('heart') >= 0 || sel.id.indexOf('lung') >= 0 || sel.id.indexOf('liver') >= 0 || sel.id.indexOf('stomach') >= 0 || sel.id.indexOf('intestin') >= 0));
